    image_patch = ImagePatch(image)
    chairs = image_patch.find("chair")
    stripped_chairs = [c for c in chairs if c.verify_property("chair", "stripped")]
    if not stripped_chairs: return image_patch
    stripped_chairs.sort(key=lambda c: c.horizontal_center)
    for i, chair in enumerate(chairs):
        if chair in stripped_chairs and (i > 0 and chairs[i-1] in stripped_chairs):
            return chair
    return stripped_chairs[0]

