    chairs = image_patch.find("chair")
    sofas = image_patch.find("sofa")
    if not chairs or not sofas:
        return image_patch
    chairs.sort(key=lambda c: c.horizontal_center)
    sofas.sort(key=lambda s: s.horizontal_center)
