def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    glasses = image_patch.find("glass")
    mugs = image_patch.find("mug")

    if not glasses or not mugs:
        return image_patch

    mug_pairs = [(m1, m2) for i, m1 in enumerate(mugs) for j, m2 in enumerate(mugs) if i < j]
    glass_between = []

    for m1, m2 in mug_pairs:
        m1_m2_distance = distance(m1, m2)
        for g in glasses:
            if is_between_3d(g, m1, m2):
                glass_between.append((g, m1_m2_distance))

    if not glass_between:
        return image_patch

    return min(glass_between, key=lambda x: x[1])[0]

